ValidationRule.errorConditionFormula:
AND(
    NOT($Setup.Case_Validation_Bypass__c.Bypass_Validation__c),
    AND(
    NOT(ISBLANK(Visitor_Phone_Search__c)),
    OR(
        /* Allow only + and digits */
        NOT(
            REGEX(
                Visitor_Phone_Search__c,
                "^\\+?[0-9]+$"
            )
        ),

        /* Digit length between 9 and 15 (ignore +) */
        LEN(
            SUBSTITUTE(Visitor_Phone_Search__c, "+", "")
        ) < 9,

        LEN(
            SUBSTITUTE(Visitor_Phone_Search__c, "+", "")
        ) > 15
    )
)
)
